CREATE TABLE IF NOT EXISTS event_leads(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,event_type TEXT NOT NULL,contact_name TEXT NOT NULL,contact_email TEXT,contact_phone TEXT,event_date TEXT,guest_count INTEGER,budget_cents INTEGER,source TEXT NOT NULL DEFAULT 'DIRECT',status TEXT NOT NULL DEFAULT 'NEW',assigned_digital_role TEXT NOT NULL DEFAULT 'DIGITAL_EVENT_MANAGER',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_portfolios(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,lead_id TEXT NOT NULL,event_name TEXT NOT NULL,event_type TEXT NOT NULL,stage TEXT NOT NULL DEFAULT 'DISCOVERY',owner_role TEXT NOT NULL,requirements_json TEXT NOT NULL DEFAULT '{}',risk_flags_json TEXT NOT NULL DEFAULT '[]',next_action TEXT,next_action_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(lead_id) REFERENCES event_leads(id));
CREATE TABLE IF NOT EXISTS event_documents(id TEXT PRIMARY KEY,portfolio_id TEXT NOT NULL,document_type TEXT NOT NULL,template_version TEXT NOT NULL,content_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',document_object_key TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(portfolio_id) REFERENCES event_portfolios(id));
CREATE TABLE IF NOT EXISTS event_workflow_tasks(id TEXT PRIMARY KEY,portfolio_id TEXT NOT NULL,task_code TEXT NOT NULL,title TEXT NOT NULL,assigned_role TEXT NOT NULL,automation_mode TEXT NOT NULL DEFAULT 'ASSISTED',status TEXT NOT NULL DEFAULT 'OPEN',due_at TEXT,evidence_json TEXT NOT NULL DEFAULT '{}',completed_at TEXT,FOREIGN KEY(portfolio_id) REFERENCES event_portfolios(id));
CREATE TABLE IF NOT EXISTS event_communications(id TEXT PRIMARY KEY,portfolio_id TEXT NOT NULL,channel TEXT NOT NULL,direction TEXT NOT NULL DEFAULT 'OUTBOUND',message_text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',sent_at TEXT,created_at TEXT NOT NULL,FOREIGN KEY(portfolio_id) REFERENCES event_portfolios(id));
CREATE TABLE IF NOT EXISTS event_audit_events(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,portfolio_id TEXT,event_type TEXT NOT NULL,actor_type TEXT NOT NULL,actor_id TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_event_lead_scope ON event_leads(organization_id,property_id,status,event_date);
CREATE INDEX IF NOT EXISTS idx_event_portfolio_scope ON event_portfolios(organization_id,property_id,stage,next_action_at);
